class RequestBuilder {
  constructor(app, method, urlPath) {
    this.app = app;
    this.method = method;
    this.urlPath = urlPath;
    this._headers = {};
    this._body = null;
  }

  set(header, value) {
    this._headers[header.toLowerCase()] = value;
    return this;
  }

  send(data) {
    this._body = data;
    return this;
  }

  expect(val) {
    return this;
  }

  then(resolve, reject) {
    return this._execute().then(resolve, reject);
  }

  async _execute() {
    const req = {
      method: this.method,
      url: this.urlPath,
      headers: this._headers,
      body: this._body
    };

    const res = {
      statusCode: 200,
      headers: {},
      body: null,
      status(code) {
        this.statusCode = code;
        return this;
      },
      setHeader(key, value) {
        this.headers[key] = value;
        return this;
      },
      json(data) {
        this.setHeader('Content-Type', 'application/json');
        this.body = data;
        return this;
      },
      send(data) {
        this.body = data;
        return this;
      },
      end() {
        return this;
      }
    };

    const response = await this.app.handleRequest(req, res);

    return {
      status: response.statusCode,
      statusCode: response.statusCode,
      body: response.body,
      text: typeof response.body === 'object' ? JSON.stringify(response.body) : String(response.body),
      headers: response.headers
    };
  }
}

function supertest(app) {
  return {
    get: (urlPath) => new RequestBuilder(app, 'GET', urlPath),
    post: (urlPath) => new RequestBuilder(app, 'POST', urlPath),
    put: (urlPath) => new RequestBuilder(app, 'PUT', urlPath),
    delete: (urlPath) => new RequestBuilder(app, 'DELETE', urlPath)
  };
}

module.exports = supertest;
